    lines = input_data.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())

    initial = []
    growth = []
    for line in lines[1:n+1]:
        h, a = map(int, line.split())
        initial.append(h)
        growth.append(a)

    def check(max_h):
        needed = []
        for i in range(n):
            final_no_hits = initial[i] + growth[i] * m
            if final_no_hits <= max_h:
                needed.append(0)
            else:
                needed.append(max(0, (final_no_hits - max_h + p - 1) // p))

        total_needed = sum(needed)
        if total_needed == 0:
            return True
        if total_needed > m * k:
            return False

        # Greedy simulation
        copies = needed[:]
        for _ in range(m):
            if all(x == 0 for x in copies):
                break
            picks = []
            for i in range(n):
                if copies[i] > 0:
                    picks.append((i, growth[i]))
            if not picks:
                break

            # Sort by growth rate (descending)
            picks.sort(key=lambda x: x[1], reverse=True)
            limit = min(k, len(picks))
            for i in range(limit):
                copies[picks[i][0]] -= 1
            picks = []  # Avoid reusing

        return True

    lo, hi = 0, 2 * 10**15
    ans = hi

    for _ in range(60):
        mid = (lo + hi) // 2
        if check(mid):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1

    return str(ans)

