    """
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return "-1\n"

    n, m = map(int, lines[0].split())

    graph = [[] for _ in range(n + 1)]

    # Parse all edges
    idx = 1
    for _ in range(m):
        if idx < len(lines):
            parts = lines[idx].split()
            idx += 1
            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                graph[u].append(v)
                graph[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            visited[i] = True
            size = 0
            queue = [i]
            while queue:
                node = queue.pop(0)
                size += 1
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    # Generate lucky numbers up to n
    lucky = set()

    def generate_lucky(current):
        if current == 0:
            generate_lucky(4)
            generate_lucky(7)
            return
        if current > n:
            return
        if current > 0:
            lucky.add(current)
        generate_lucky(current * 10 + 4)
        generate_lucky(current * 10 + 7)

    generate_lucky(0)
    lucky_sorted = sorted(lucky)

    # Check if any component is already lucky
    if any(size in lucky_sorted for size in component_sizes):
        return "0\n"

    # DP to find minimum components needed for each lucky size
    INF = float('inf')
    min_components = [INF] * (n + 1)
    min_components[0] = 0

    for size in component_sizes:
        for i in range(size, n + 1):
            if min_components[i - size] + 1 < min_components[i]:
                min_components[i] = min_components[i - size] + 1

    # Find minimum roads for any lucky number
    ans = INF
    for lucky_num in lucky_sorted:
        if min_components[lucky_num] < INF:
            # Roads needed = components - 1
            roads = min_components[lucky_num] - 1
            ans = min(ans, roads)

    if ans == INF:
        return "-1\n"
    return f"{ans}\n"

