# Conftest for pytest patching

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    n, m = map(int, lines[0].split())
    grid = lines[1:]

    def can_form_palindrome(s):
        """Check if string can be rearranged to form a palindrome"""
        counts = {}
        for ch in s:
            counts[ch] = counts.get(ch, 0) + 1
        odd_count = 0
        for count in counts.values():
            if count % 2 == 1:
                odd_count += 1
        return odd_count <= 1

    ans = 0

    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    # Check if each row in submatrix can form a palindrome
                    rows_ok = True
                    for r in range(r1, r2 + 1):
                        if not can_form_palindrome(grid[r][c1:c2+1]):
                            rows_ok = False
                            break

                    if not rows_ok:
                        continue

                    # Check if columns can form palindromes after row reordering
                    # For a column to be a palindrome, its character count must allow
                    cols_ok = True
                    for c in range(c1, c2 + 1):
                        col = [grid[r][c] for r in range(r1, r2 + 1)]
                        if not can_form_palindrome(col):
                            cols_ok = False
                            break

                    if cols_ok:
                        ans += 1

    return str(ans) + '\n'

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    memo = {}

    def get_grundy(n):
        if n == 0:
            return 0
        if n in memo:
            return memo[n]

        # Option 1: Remove one cow
        reachable = {get_grundy(n - 1)}

        # Option 2: Split if n is even
        if n % 2 == 0:
            x = n // 2
            if k % 2 == 1:  # k is odd: k copies of g(x) XOR to g(x)
                reachable.add(get_grundy(x))
            else:  # k is even: k copies XOR to 0
                reachable.add(0)

        # Compute mex (minimum excluded value)
        g = 0
        while g in reachable:
            g += 1

        memo[n] = g
        return g

    xor_sum = 0
    for x in a:
        xor_sum ^= get_grundy(x)

    return "Kevin\n" if xor_sum != 0 else "Nicky\n"

