    adj = [[] for _ in range(2 * m)]

    def to_node(lit):
        """Convert literal to node index"""
        return (1 if lit < 0 else 0) + 2 * (abs(lit) - 1)

    def neg_node(lit):
        """Convert literal to negation node"""
        return to_node(lit) ^ 1

    # Build implication graph
    # For clause (l1 ∨ l2 ∨ ... ∨ lk), add all pairs: ¬li → lj and ¬lj → li
    for clause in clauses:
        k = len(clause)
        for i in range(k):
            for j in range(i + 1, k):
                l1, l2 = clause[i], clause[j]
                adj[neg_node(l1)].append(to_node(l2))
                adj[neg_node(l2)].append(to_node(l1))

    # Kosaraju's algorithm for SCC
    visited = [False] * (2 * m)
    order = []

    def dfs1(v):
        visited[v] = True
