from typing import List, Tuple

def solution(input_str: str) -> str:
    """
    Arranges sheep in a line to minimize the maximum distance between tied sheep.
    Sheep are tied when their grazing ranges overlap.
    Distance = number of sheep between the two tied sheep in the arrangement.

    Approach:
    1. Build an intersection graph where edges connect overlapping ranges
    2. Find connected components (groups of sheep that can/are tied together)
    3. Within each component, sort by right endpoint to keep intersecting pairs close
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    ranges = []
    for i in range(1, n + 1):
        li, ri = map(int, lines[i].split())
        ranges.append((li, ri, i))  # Store (left, right, original_index)

    num_sheep = n
    adj = [[] for _ in range(num_sheep)]

    # Build intersection graph
    for i in range(num_sheep):
        for j in range(i + 1, num_sheep):
            # Check if ranges [li, ri] and [lj, rj] overlap
            l1, r1 = ranges[i][0], ranges[i][1]
            l2, r2 = ranges[j][0], ranges[j][1]
            if max(l1, l2) <= min(r1, r2):
                adj[i].append(j)
                adj[j].append(i)

    # Find connected components
    visited = [False] * num_sheep
    components = []
    for i in range(num_sheep):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)

    # Sort components and sort within each component by right endpoint
    components.sort(key=lambda c: min(ranges[i][1] for i in c))

    result = []
    for comp in components:
        comp_sorted = sorted(comp, key=lambda x: ranges[x][1])
        for sheep_idx in comp_sorted:
            result.append(ranges[sheep_idx][2])

    return ' '.join(map(str, result)) + '\n'


