from itertools import combinations, product

def solution(s):
    # Parse input
    parts = s.strip().split('\n')
    n, r = map(int, parts[0].split())

    # Generate all valid lattice points within radius r
    # x² + y² ≤ r²
    valid_points = []
    for x in range(-r - 1, r + 2):
        for y in range(-r - 1, r + 2):
            if x * x + y * y <= r * r:
                valid_points.append((x, y))

    best_score = -1
    best_config = []

    # Strategy: Try to place points at extreme positions on different axes
    # This greedy approach works well for small n

    if r == 1:
        # For small r, the optimal is to have symmetric points
        if n <= 4:
            # Max distance is 2, between opposite points
            result = []
            for _ in range(n // 2):
                result.append((0, 1))
                result.append((0, -1))
            if n % 2 == 1:
                result.append((0, 0)) or result.append((0, 0))
            else:
                result = [(-1, 0)] * (n // 2) + [(1, 0)] * (n // 2)

            best_config = result
            best_score = compute_score(result)
        else:
            # Done.

    # Now try brute force for small cases
    if n <= 6:
        for config in product(valid_points, repeat=n):
            score = compute_score(list(config))
            if score > best_score:
                best_score = score
                best_config = list(config)

    # Output
    lines = [str(best_score)] + [f"{p[0]} {p[1]}" for p in best_config]
    return '\n'.join(lines)

def compute_score(config):
    score = 0
    for i in range(len(config)):
        for j in range(i + 1, len(config)):
            dx = config[i][0] - config[j][0]
            dy = config[i][1] - config[j][1]
            score += dx * dx + dy * dy
    return score

