    MOD = 10**9 + 7
    MOD_minus_1 = MOD - 1

    def factorize(n, d=2):
        """Returns all prime factors with their counts"""
        result = {}
        while d * d <= n:
            while n % d == 0:
                result[d] = result.get(d, 0) + 1
                n //= d
            d += 1 if d == 2 else 2
        if n > 1:
            result[n] = result.get(n, 0) + 1
        return result

    def mat_mul(A, B):
        C = [[0] * 5 for _ in range(5)]
        for i in range(5):
            for k in range(5):
                if A[i][k] == 0:
                    continue
                for j in range(5):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD_minus_1
        return C

    def mat_pow(A, n):
        result = [[0] * 5 for _ in range(5)]
        for i in range(5):
