def isprime(p):
    """Check if p is prime."""
    if p < 2:
        return False
    if p == 2:
        return True
    if p % 2 == 0:
        return False
    i = 3
    while i * i <= p:
        if p % i == 0:
            return False
        i += 2
    return True

def get_prime_factors(n):
    """Get all unique prime factors of n."""
    if n <= 1:
        return []
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors

def is_primitive_root(b, p):
    """Check if b is a primitive root modulo prime p."""
    if p == 2:
        return b % 2 == 1 and b != 1

    if gcd(b, p) != 1:
        return False

    n = p - 1
    factors = get_prime_factors(n)

    for q in factors:
        exponent = n // q
        if pow(b, exponent, p) == 1:
            return False
    return True

