def compute_component_gcds():
    """Helper to compute GCDs of all cycles in each component"""
    sys.setrecursionlimit(300000)
    n, m = map(int, __import__('sys').input().split())

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b, l = map(int, input().split())
        adj[a].append((b, l))

    q = int(input())
    queries = []
    for _ in range(q):
        queries.append(tuple(map(int, input().split())))

    visited = [False] * (n + 1)
    dist_from_start = {}

    # For efficiency, we'll use GCD of closed walk distances
    # Use BFS since we can't handle cycles with DFS due to graph being directed

    gcd_cache = {}

    for start in range(1, n + 1):
        if visited[start]:
            continue

        # DFS to find all cycle distances in component
        stack = [(start, start, 0)]  # (node, path_length, distance)
        in_stack = {start}
        component_nodes = set()
        gcd_val = 0

        while stack:
            node, path_len, dist = stack.pop()
            component_nodes.add(node)
            visited[node] = True
            dist_from_start[node] = dist

            for neighbor, length in adj[node]:
                if neighbor in in_stack:
                    # Found a cycle
                    cycle_dist = dist + length - dist_from_start[neighbor]
                    if cycle_dist > 0:
                        gcd_val = gcd(gcd_val, cycle_dist)
                in_stack.discard(node)
                in_stack.add(neighbor)
                stack.append((neighbor, path_len + 1, dist + length))

        gcd_cache[start] = gcd_val if gcd_val != 0 else None

    # Output results
