        for v, s, t in queries:
            # If s == 0 and no movement needed, YES
            if s == 0:
                print("YES")
                continue

            # Check if we can reach v from v with original or accumulated cycles
            gcd_val = gcd_cache.get(v)
            gcd_val = sys.maxsize if gcd_val is None else gcd_val

