    def normalize(u, v):
        if u < v:
            return (u, v)
        return (v, u)

    def clockwise_between(a, b, x, n):
        """Check if x lies strictly clockwise from a to b (not at endpoints)"""
        if a == b:
            return False
        if a < b:
            return a < x < b
        else:  # wraparound: a -> n-1 -> 0 -> ... -> b
            return x > a or x < b

    def crosses(n, a, b, c, d):
        """Check if chord (a,b) crosses chord (c,d) with NO shared endpoints"""
        if len(set([a, b]) & set([c, d])) != 0:
            return False  # share an endpoint

        a, b = normalize(a, b)
        c, d = normalize(c, d)

        c_internal = clockwise_between(a, b, c, n)
        d_internal = clockwise_between(a, b, d, n)

        return (c_internal and not d_internal) or (d_internal and not c_internal)

    conflict = [[] for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            a, b = edges[i]
            c, d = edges[j]

            if crosses(n, a, b, c, d):
                conflict[i].append(j)
                conflict[j].append(i)

    colors = [-1] * m
    valid = True

    for i in range(m):
        if colors[i] == -1:
            colors[i] = 0
            stack = [(i, 0)]

