        if len(parts) < 2:
            continue
        a, b = int(parts[0]), int(parts[1])

        result = find_best_match(a, b)
        if result is None:
            results.append("Impossible")
        else:
            results.append(result)

    return "\n".join(results) + "\n"


def valid_set(a, b):
    """Check if (a,b) is a valid volleyball set score"""
    # Team A wins
    if a >= 25:
        if a - b >= 2:
            return True
        if a == 24 and b == 23:  # Special deuce start for set 5
            return True
    # Team B wins
    if b >= 25:
        if b - a >= 2:
            return True
        if b == 24 and a == 23:
            return True
    # Check for 24-24 or 14-14 pattern completion
    if a == 25 and b == 24:
        return True
    if b == 25 and a == 24:
        return True
    if a == 15 and b == 14:
        return True
    if b == 15 and a == 14:
        return True
    return False


def find_best_match(total_a, total_b):
    """Find best match score for Team A maximizing set difference"""
    return find_valid_try_ordering(
        total_a, total_b,
        [('3-0', 3, 0, 0)],
        [('3-0', 3, 0, 0)] + [
            ('3-1', 3, 1, 0),
            ('3-2', 3, 2, 0),
            ('2-3', 2, 3, 0),
            ('1-3', 1, 3, 0),
            ('0-3', 0, 3, 0)
        ][1:],
        [('3-1', 3, 1, 0)] + [
            ('3-2', 3, 2, 0),
            ('0-3', 0, 3, 0),
            ('1-3', 1, 3, 0),
            ('2-3', 2, 3, 0)
        ][1:],
        [('3-2', 3, 2, 0)] + [
            ('0-3', 0, 3, 0),
            ('1-3', 1, 3, 0),
            ('2-3', 2, 3, 0)
        ][1:]
    )


def find_valid_try_ordering(total_a, total_b, best_attempts_second_worse, extra_attempts_worst):
    for attempt_order in [best_attempts_second_worse, extra_attempts_worst]:
        for score_str, sets_by_a, sets_by_b, _ in attempt_order:
            result = find_distribution(total_a, total_b, int(sets_by_a), int(sets_by_b))
            if result is not None:
                return f"{score_str}:{sets_by_b}:{sets_by_a} \n{result} "
    return None


def find_distribution(total_a, total_b, sets_by_a, sets_by_b):
    """Find valid distribution of sets where A wins sets_by_a and B wins sets_by_b"""

    # Generate possible set score combinations
    possible = []

    def generate_valid_sets():
        return [(a, b) for a in range(101) for b in range(101) if valid_set(a, b)]

    valid_sets = generate_valid_sets()

    def backtrack(idx, a_used, b_used, sets):
        if idx == len(score_str):
            return a_used == total_a and b_used == total_b
        for va, vb in valid_sets:
            if a_used + va <= total_a and b_used + vb <= total_b:
                if backtrack(idx + 1, a_used + va, b_used + vb, [*(sets, (va, vb))]):
                    return f"{' '.join(f'{va}:{vb}' for va, vb in sets)} "
        return False

    return backtrack(0, 0, 0, [])

def solution(input_str):
