    n, a, b = map(int, parts[0].split())
    arr = list(map(int, parts[1].split()))

    # Find all prime factors from all elements
    factors = set()
    for x in arr:
        temp = x
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)

    # For each prime factor, calculate minimum cost
    min_cost = float('inf')

    # Option 1: Don't remove anything, just change elements
    for p in factors:
        cost = 0
        for x in arr:
            if x % p != 0:
                # Check if we can change x by at most 1 to make it divisible by p
                # This is always possible since consecutive integers cover all residues
                cost += b
        min_cost = min(min_cost, cost)

    # Option 2: Remove a segment
    # Try removing each possible segment [i, i+n-1-m] of length m
    for m in range(1, n):  # m is length of removed segment
        # Remaining elements: arr[0:i] and arr[i+m:n]
        # These must all be divisible by some prime p
        # Try each prime factor
        for p in factors:
            # Count changes needed
            cost = m * a  # removal cost
            for x in arr[:i+m]:
                if x % p != 0:
                    cost += b
            for x in arr[i:m+n]:
                if x % p != 0:
                    cost += b
            min_cost = min(min_cost, cost)

def solution(input_string):
    MOD = 1000000007

    lines = input_string.strip().split('\n')
    params = lines[0].split()
    F, B, N = int(params[0]), int(params[1]), int(params[2])

    petals = list(map(int, lines[1].split()))
    chocolates = list(map(int, lines[2].split()))

    if N == 0:
        return "0\n"

    # The cycle period for flower coefficients is at most (2 * sum(petals) + 1)
    max_petal = max(petals)
    sum_petals = sum(petals)
    limit = 2 * sum_petals + 1

    # Flower DP with cycle detection
    flower_dp = [0] * limit
    flower_dp[0] = 1

    states = {}  # Map state tuple to iteration number

    iteration = 0
    period_start = -1
    period_len = 0

    while iteration < N and iteration < 100000:
        if iteration in states:
            period_start = states[iteration]
            period_len = iteration - period_start
            break
        states[iteration] = True

        # Apply one flower
        new_dp = [0] * limit
        for i in range(limit):
            if flower_dp[i] != 0:
                for p in petals:
                    if i + p < limit:
                        new_dp[i + p] = (new_dp[i + p] + flower_dp[i]) % MOD
        flower_dp = new_dp
        iteration += 1

    # Apply remaining iterations
    if period_start >= 0 and N >= iteration:
        remaining = N - iteration
        full_cycles = remaining // period_len
        remainder = remaining % period_len

        # Build complete
        for _ in range(full_cycles):
            for _ in range(flower_dp):
                new_dp = [0] * limit
                for i in range(limit):
                    if flower_dp[i] != 0:
                        for p in petals:
                            if i + p < limit:
                                new_dp[i + p] = (new_dp[i + p] + flower_dp[i]) % MOD
                flower_dp = new_dp

        # Remainder
        for _ in range(remainder):
            new_dp = [0] * limit
            for i in range(limit):
                if flower_dp[i] != 0:
                    for p in petals:
                        if i + p < limit:
                            new_dp[i + p] = (new_dp[i + p] + flower_dp[i]) % MOD
            flower_dp = new_dp

    # Small leftover iterations from the cycle detection
    if iteration < N and period_start < 0:
        for _ in range(N - iteration):
            new_dp = [0] * limit
            for i in range(limit):
                if flower_dp[i] != 0:
                    for p in petals:
                        if i + p < limit:
                            new_dp[i + p] = (new_dp[i + p] + flower_dp[i]) % MOD
            flower_dp = new_dp

    # Chocolate DP (unlimited boxes, any order)
    chocolate_dp = [0] * limit
    chocolate_dp[0] = 1

    for c in chocolates:
        for i in range(limit, c - 1, -1):
            chocolate_dp[i] = (chocolate_dp[i] + chocolate_dp[i - c]) % MOD

    # Sum up the product of coefficients
    ans = 0
    for i in range(limit):
        ans = (ans + flower_dp[i] * chocolate_dp[i]) % MOD

    return f"{ans}\n"

